options.elementValueChanged:
if (context.element.id === 'metric_pick') {
  const v = String(context.element.value ?? '').trim();
  context.grafana.locationService.partial({'var-edit_metric': v}, true);
  const syncObj = {};
  syncObj['metric_pick'] = v;
  context.panel.setFormValue(syncObj);
  if (!v) {
    context.panel.setFormValue({ metric: '', display_name: '', unit: '', visible: true, alarm_low: null, alarm_high: null });
  }
  const focusPrimaryField = () => {
    if (typeof document === 'undefined') return;
    const selectors = [
      'input[name="metric"]',
      'textarea[name="metric"]',
      'input[id="metric"]',
      '[aria-label="metric"]',
      '[data-testid*="metric"] input',
    ];
    for (const selector of selectors) {
      const el = document.querySelector(selector);
      if (el && typeof el.focus === 'function') {
        el.focus();
        if (typeof el.select === 'function') {
          el.select();
        }
        break;
      }
    }
  };
  setTimeout(focusPrimaryField, 0);
  setTimeout(focusPrimaryField, 120);
}

